import { Routes } from '@angular/router';

export const routes: Routes = [
  { path: '', pathMatch: 'full', redirectTo: 'dashboard' },
  {
    path: 'dashboard',
    loadComponent: () => import('./dashboard/dashboard').then((m) => m.Dashboard),
  },
  {
    path: 'roster',
    loadComponent: () => import('./heroes/heroes').then((m) => m.Heroes),
  },
  {
    path: 'detail/:id',
    loadComponent: () => import('./hero-detail/hero-detail').then((m) => m.HeroDetail),
  },
  {
    path: 'missions',
    loadComponent: () => import('./missions/missions').then((m) => m.Missions),
  },
  {
    path: 'recruit',
    loadComponent: () => import('./recruit/recruit').then((m) => m.Recruit),
  },
  {
    path: 'threats',
    loadComponent: () => import('./threats/threats').then((m) => m.Threats),
  },
  {
    path: 'settings',
    loadComponent: () => import('./settings/settings').then((m) => m.Settings),
  },
];
import { Component, inject } from '@angular/core';
import { RouterLink, RouterLinkActive, RouterOutlet } from '@angular/router';
import { NgIcon, provideIcons } from '@ng-icons/core';
import {
  lucideBell,
  lucideChevronRight,
  lucideCrosshair,
  lucideLayoutDashboard,
  lucideMoon,
  lucideSearch,
  lucideSettings,
  lucideShieldAlert,
  lucideSun,
  lucideTarget,
  lucideUserPlus,
  lucideUsers,
} from '@ng-icons/lucide';
import { HlmAvatarImports } from '@spartan-ng/helm/avatar';
import { HlmButtonImports } from '@spartan-ng/helm/button';
import { HlmInputImports } from '@spartan-ng/helm/input';
import { HlmSidebarImports } from '@spartan-ng/helm/sidebar';
import { HlmTooltipImports } from '@spartan-ng/helm/tooltip';
import { AppViewModel } from './app.view-model';

@Component({
  selector: 'app-root',
  imports: [
    RouterOutlet,
    RouterLink,
    RouterLinkActive,
    NgIcon,
    HlmSidebarImports,
    HlmButtonImports,
    HlmInputImports,
    HlmTooltipImports,
    HlmAvatarImports,
  ],
  providers: [
    AppViewModel,
    provideIcons({
      lucideBell,
      lucideChevronRight,
      lucideCrosshair,
      lucideLayoutDashboard,
      lucideMoon,
      lucideSearch,
      lucideSettings,
      lucideShieldAlert,
      lucideSun,
      lucideTarget,
      lucideUserPlus,
      lucideUsers,
    }),
  ],
  templateUrl: './app.html',
  styleUrl: './app.css',
})
export class App {
  protected readonly vm = inject(AppViewModel);
}
<div hlmSidebarWrapper class="app">
  <hlm-sidebar>
    <div hlmSidebarHeader class="app__brand">
      <ng-icon name="lucideCrosshair" class="app__brand-icon" aria-hidden="true" />
      <span>Hero Ops Console</span>
    </div>

    <div hlmSidebarContent>
      <nav aria-label="Primary">
        <div hlmSidebarGroup>
          <div hlmSidebarGroupLabel>Operations</div>
          <div hlmSidebarGroupContent>
            <ul hlmSidebarMenu>
              @for (item of vm.navItems; track item.path) {
                <li hlmSidebarMenuItem>
                  <a
                    hlmSidebarMenuButton
                    [routerLink]="item.path"
                    routerLinkActive
                    #active="routerLinkActive"
                    [isActive]="active.isActive"
                  >
                    <ng-icon [name]="item.icon" aria-hidden="true" />
                    <span>{{ item.label }}</span>
                  </a>
                </li>
              }
            </ul>
          </div>
        </div>
      </nav>
    </div>

    <div hlmSidebarFooter class="app__footer">
      <p class="app__footer-note">Example data: demo console</p>
    </div>
  </hlm-sidebar>

  <main hlmSidebarInset class="app__main">
    <header class="app__topbar">
      <button hlmSidebarTrigger class="app__menu"></button>

      <nav aria-label="Breadcrumb" class="app__crumbs">
        <ol class="app__crumb-list">
          @for (crumb of vm.crumbs(); track $index; let last = $last) {
            <li class="app__crumb">
              @if (last || !crumb.path) {
                <span class="app__crumb-current" aria-current="page">{{ crumb.label }}</span>
              } @else {
                <a class="app__crumb-link" [routerLink]="crumb.path">{{ crumb.label }}</a>
              }
              @if (!last) {
                <ng-icon name="lucideChevronRight" class="app__crumb-sep" aria-hidden="true" />
              }
            </li>
          }
        </ol>
      </nav>

      <div class="app__search">
        <ng-icon name="lucideSearch" class="app__search-icon" aria-hidden="true" />
        <input
          hlmInput
          #search
          type="search"
          class="app__search-input"
          placeholder="Search heroes and missions"
          aria-label="Search heroes and missions"
          [value]="vm.query()"
          (input)="vm.setQuery(search.value)"
        />
      </div>

      <div class="app__actions">
        <button
          hlmBtn
          variant="ghost"
          size="icon"
          type="button"
          hlmTooltip="Notifications"
          aria-label="Notifications"
        >
          <ng-icon name="lucideBell" aria-hidden="true" />
        </button>

        <button
          hlmBtn
          variant="ghost"
          size="icon"
          type="button"
          [hlmTooltip]="vm.themeLabel()"
          [attr.aria-label]="vm.themeLabel()"
          (click)="vm.toggleTheme()"
        >
          <ng-icon [name]="vm.themeIcon()" aria-hidden="true" />
        </button>

        <hlm-avatar class="app__avatar" role="img" aria-label="Signed-in commander">
          <span hlmAvatarFallback>CO</span>
        </hlm-avatar>
      </div>
    </header>

    <div class="app__content">
      <router-outlet />
    </div>
  </main>
</div>
import { toSignal } from '@angular/core/rxjs-interop';
import { DestroyRef, DOCUMENT, Injectable, computed, effect, inject, signal } from '@angular/core';
import { NavigationEnd, Router } from '@angular/router';
import { filter, map } from 'rxjs';

export interface NavItem {
  readonly path: string;
  readonly label: string;
  readonly icon: string;
}

export interface Crumb {
  readonly label: string;
  readonly path?: string;
}

const THEME_KEY = 'hero-ops-theme';
const DARK_QUERY = '(prefers-color-scheme: dark)';

// The hero detail screen is reached from the roster, so it is not a rail destination.
const NAV_ITEMS: readonly NavItem[] = [
  { path: '/dashboard', label: 'Dashboard', icon: 'lucideLayoutDashboard' },
  { path: '/roster', label: 'Roster', icon: 'lucideUsers' },
  { path: '/missions', label: 'Missions', icon: 'lucideTarget' },
  { path: '/threats', label: 'Threats', icon: 'lucideShieldAlert' },
  { path: '/recruit', label: 'Recruit', icon: 'lucideUserPlus' },
  { path: '/settings', label: 'Settings', icon: 'lucideSettings' },
];

const SECTION_LABELS: Partial<Record<string, string>> = {
  dashboard: 'Dashboard',
  roster: 'Roster',
  missions: 'Missions',
  recruit: 'Recruit',
  threats: 'Threats',
  settings: 'Settings',
};

function readStoredTheme(win: Window | null): 'light' | 'dark' | null {
  try {
    const value = win?.localStorage.getItem(THEME_KEY);
    return value === 'light' || value === 'dark' ? value : null;
  } catch {
    return null;
  }
}

@Injectable()
export class AppViewModel {
  private readonly document = inject(DOCUMENT);
  private readonly router = inject(Router);
  private readonly win = this.document.defaultView;
  private readonly systemDark = this.win?.matchMedia?.(DARK_QUERY) ?? null;
  private readonly stored = readStoredTheme(this.win);

  readonly navItems = NAV_ITEMS;
  readonly query = signal('');
  private readonly isDark = signal(this.stored ? this.stored === 'dark' : (this.systemDark?.matches ?? false));
  readonly themeIcon = computed(() => (this.isDark() ? 'lucideSun' : 'lucideMoon'));
  readonly themeLabel = computed(() =>
    this.isDark() ? 'Switch to light theme' : 'Switch to dark theme',
  );

  private readonly url = toSignal(
    this.router.events.pipe(
      filter((event): event is NavigationEnd => event instanceof NavigationEnd),
      map((event) => event.urlAfterRedirects),
    ),
    { initialValue: '/' },
  );

  readonly crumbs = computed<readonly Crumb[]>(() => {
    const [section = '', id] = this.url().split(/[?#]/)[0].split('/').filter(Boolean);
    if (section === 'detail' && id) {
      return [{ label: 'Roster', path: '/roster' }, { label: `Hero ${id}` }];
    }
    return [{ label: SECTION_LABELS[section] ?? 'Dashboard' }];
  });

  constructor() {
    effect(() => this.document.documentElement.classList.toggle('dark', this.isDark()));

    // With no stored choice, follow the operating system's colour scheme as it changes.
    const onSystemChange = (event: MediaQueryListEvent) => {
      if (readStoredTheme(this.win) === null) this.isDark.set(event.matches);
    };
    this.systemDark?.addEventListener('change', onSystemChange);
    inject(DestroyRef).onDestroy(() =>
      this.systemDark?.removeEventListener('change', onSystemChange),
    );
  }

  toggleTheme(): void {
    const next = !this.isDark();
    this.isDark.set(next);
    try {
      this.win?.localStorage.setItem(THEME_KEY, next ? 'dark' : 'light');
    } catch {
      // Storage is unavailable (private mode, blocked cookies): the choice still applies this visit.
    }
  }

  setQuery(value: string): void {
    this.query.set(value);
  }
}
import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideRouter } from '@angular/router';
import { provideSpartanHlm } from '@spartan-ng/helm/utils';
import { routes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
